package com.bank.qa.strategy;

import java.util.function.BooleanSupplier;

// A single test case: a name, the scope it belongs to, and the check to run.
class TestCase {
    private final String name;
    private final TestScope scope;
    private final BooleanSupplier check;

    TestCase(String name, TestScope scope, BooleanSupplier check) {
        this.name = name;
        this.scope = scope;
        this.check = check;
    }

    String getName() { return name; }
    TestScope getScope() { return scope; }
    boolean run() { return check.getAsBoolean(); }
}
