package com.bank.qa.strategy;

import java.util.List;
import java.util.logging.Logger;

// Filters cases by scope and runs them, returning true only if all pass.
class TestRunner {
    private static final Logger log = Logger.getLogger(TestRunner.class.getName());
    private final List<TestCase> allCases;

    TestRunner(List<TestCase> allCases) { this.allCases = allCases; }

    boolean runScope(TestScope scope) {
        int total = 0, passed = 0;
        for (TestCase c : allCases) {
            if (c.getScope() != scope) continue;
            total++;
            boolean ok = c.run();
            if (ok) {
                passed++;
                log.info("PASS [" + scope + "] " + c.getName());
            } else {
                log.severe("FAIL [" + scope + "] " + c.getName());
            }
        }
        boolean allPassed = passed == total && total > 0;
        log.info(scope + " suite: " + passed + "/" + total
                + (allPassed ? " PASSED" : " FAILED"));
        return allPassed;
    }
}
